mapper.select:


    del_flag = '0'

        and (
            name_cn ILIKE CONCAT('%', #{searchQuery}, '%')
            or name_vn ILIKE CONCAT('%', #{searchQuery}, '%')
            or name_en ILIKE CONCAT('%', #{searchQuery}, '%')
            or abbreviation ILIKE CONCAT('%', #{searchQuery}, '%')
            or core_responsibilities ILIKE CONCAT('%', #{searchQuery}, '%')
        )


        and level = #{level}


        and category = #{category}


        and province = #{province}


order by update_time desc nulls last, name_cn asc
